#!/bin/sh
# Regenerate web/src/lib/api-types.ts from the Pydantic models (the API contract).
set -eu
root=$(cd "$(dirname "$0")/.." && pwd)
py=${PYTHON:-$root/.venv/bin/python}
"$py" -m ripshelf.dev.schema > "$root/web/src/lib/api-schema.json"
cd "$root/web"
npx json2ts --input src/lib/api-schema.json --output src/lib/api-types.ts \
  --bannerComment "// Generated by scripts/gen-types.sh from src/ripshelf/models.py. Do not edit." \
  --additionalProperties false --unreachableDefinitions
rm src/lib/api-schema.json
